CREATE TABLE ETL_PROCESS.T_ETL_ORDER_POSITION (
   CUST_ORDER_SID                      NUMBER          NOT NULL COMMENT 'The unique identifier (surrogate key) for customer order',
   CUST_ORDER_CREATE_TMSP              TIMESTAMP_TZ(9) COMMENT 'The date and time when order was created in source system ( is used in reporting)',
   PROD_VARIANT_SID                    NUMBER          COMMENT 'Ordered product',
   CUST_ORDER_NR                       VARCHAR(20)     NOT NULL COMMENT 'The original order number of the source system',
   CUST_ORDER_POS_NR                   NUMBER          NOT NULL COMMENT 'The particular position number of an item in an order',
   REFERENCE_DOCUMENT_ORDER_SID        NUMBER          COMMENT 'The unique identifier for the reference document order',
   REFERENCE_DOCUMENT_ORDER_NR         VARCHAR(20)     COMMENT 'The original order number of the reference document',
   REFERENCE_DOCUMENT_ORDER_POS_NR     NUMBER          COMMENT 'The particular order position number of the reference document',
   PROD_QTY                            NUMBER(38, 5)   COMMENT 'Quantity of a particular product ordered',
   BUNDLE_HEADER_POS_NR                NUMBER          COMMENT 'In case of a line being a composition part of the bundle-header (see bundle header code field), it can be allocated with this field to its header item',
   CURR_CD                             VARCHAR(5)      COMMENT 'Currency code in which order has been payed',
   PROD_PRICE_NET_LOCAL_VAL            NUMBER(38, 5)   COMMENT 'Original (listed) net price of a product in local currency',
   PROD_PRICE_VAT_LOCAL_VAL            NUMBER(38, 5)   COMMENT 'Original (listed) vat value on price of a product in local currency',
   PROD_PRICE_GROSS_LOCAL_VAL          NUMBER(38, 5)   COMMENT 'The gross local price of the product sold to customers OR the Intercompany price invoiced to the selling partner',
   PROD_COUPON_NET_LOCAL_VAL           NUMBER(38, 5)   COMMENT 'The net discount value for the (original/listed) product in local currency',
   PROD_COUPON_GROSS_LOCAL_VAL         NUMBER(38, 5)   COMMENT 'The gross discount value for the (original/listed) product in local currency',
   PROD_COUPON_VAT_LOCAL_VAL           NUMBER(38, 5)   COMMENT 'The discount vat value for the (original/listed) product in local currency',
   COGS_PRICE_NET_LOCAL_VAL            NUMBER(38, 5)   COMMENT 'Cost of Goods sold',
   DELIVERY_COST_GROSS_LOCAL_VAL       NUMBER(38, 5)   COMMENT 'Article specific gross delivery cost in local currency. This cost is optional and mostly article dependent. An example is a fridge which has additional delivery costs.',
   DELIVERY_COUPON_NET_LOCAL_VAL       NUMBER(38, 5)   COMMENT 'The net discount value for article specific delivery costs in local currency.',
   DELIVERY_COUPON_GROSS_LOCAL_VAL     NUMBER(38, 5)   COMMENT 'The gross discount value for article specific delivery costs in local currency.',
   DELIVERY_COUPON_VAT_LOCAL_VAL       NUMBER(38, 5)   COMMENT 'The discount vat value for article specific delivery costs in local currency',
   DELIVERY_PAUSHAL_NET_LOCAL_VAL      NUMBER(38, 5)   COMMENT 'A paushal for delivery costs splitted per every order position in netto and local currency',
   DELIVERY_PAUSHAL_GROSS_LOCAL_VAL    NUMBER(38, 5)   COMMENT 'A paushal for delivery costs splitted per every order position in gross and local currency',
   DELIVERY_PAUSHAL_VAT_LOCAL_VAL      NUMBER(38, 5)   COMMENT 'The vat value of the paushal delivery costs splitted per every order position in local currency',
   ADD_DELIVERY_PAUSHAL_GROSS_LOCAL_VAL NUMERIC(38,5)   COMMENT 'Additional gross delivery fee/paushal for special destinations (Distribution Zones),  splitted per every order position in local currency',
   ADD_DELIVERY_PAUSHAL_VAT_LOCAL_VAL  NUMERIC(38,5)   COMMENT 'Additional vat on delivery fee/paushal for special destinations (Distribution Zones),  splitted per every order position in local currency',
   SRC_FILE_TMSP                       TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was extracted from the source.',
   DELIVERY_PAUSHAL_COUPON_GROSS_LOCAL_VAL NUMBER(38, 5)   COMMENT 'A discount value gross for paushal delivery cost splitted per every order position in local currency',
   TAX_CLASS_CD                        VARCHAR(5)      COMMENT 'The code identifying the tax class',
   ORDER_CANCEL_REASON_CD              VARCHAR(5)      COMMENT 'The code for reason why the customer has cancelled or got been cancelled an order line/product',
   IS_ORDER_CANCEL_FG                  BOOLEAN         COMMENT 'Flag telling whether the order has been cancelled by the customer or Lidl Digital',
   IS_ORDER_MIGRATED_FG                BOOLEAN         COMMENT 'An indicator showing whether the order is migrated or not',
   CUST_DELIVERY_TGT_DT                DATE            COMMENT 'The first date which has been communicated to the customer until when the shipment is meant to arrive',
   CUST_ORDER_RETURN_CREATE_TMSP       TIMESTAMP_TZ(9) COMMENT 'Creation timestamp of the return. ',
   WH_SID                              NUMBER          COMMENT 'The unique identifier (sk) for the warehouse from where particular product will be sent',
   WH_CD                               VARCHAR(5)      COMMENT 'The code for the warehouse from where particular product will be sent',
   PROD_ASSORTMENT_CLASS_CD            VARCHAR(5)      COMMENT 'The code for the product assortment classification',
   DROPSHIPMENT_ORDER_FG               BOOLEAN         COMMENT 'In case the material is being sent from the supplier this field will be filled.',
   SHIPPING_POINT_CD                   VARCHAR(5)      COMMENT 'The code for the shipping point',
   RETURN_REASON_CD                    VARCHAR(5)      COMMENT 'The code for the return reason',
   DELIVERY_SRC_TYPE_CD                VARCHAR(5)      COMMENT 'The code for source location of product from where it is delivered i.e. from supplier or warehouse directly',
   DELIVERY_STATUS_CD                  VARCHAR(5)      COMMENT 'Code for the delivery status of the item',
   DELIVERY_STATUS_NR                  NUMBER          COMMENT 'Generated number for the code for the delivery status of the item',
   OVERALL_DELIVERY_STATUS_FOR_ITEM_CD VARCHAR(5)      COMMENT 'Code for the overall delivery status of the item',
   OVERALL_DELIVERY_STATUS_FOR_ITEM_NR NUMBER          COMMENT 'Generated number for the code for the overall delivery status of the item',
   LEAD_SRC_LOG_SYS_CD                 VARCHAR(100)    COMMENT 'Technical field - source code',
   LEAD_SRC_NAME                       VARCHAR(100)    COMMENT 'Technical field - source name ',
   PROD_CONDITION_CD                   VARCHAR(20)     COMMENT 'The condition code of the product. (01 - can be sold online, 02 - needs to be checked, 03 - for scrapping)',
   INVOICE_PRICE_NET_LOCAL_VAL         NUMBER(38, 5)   COMMENT 'Net value amount visible on the invoice. It is the net total considering all the different order positions and their respective price conditions (in case of cust_order -> sum of all different conditions, in case of internal processes what it is been paid via invoice)',
   INVOICE_PRICE_GROSS_LOCAL_VAL       NUMBER(38, 5)   COMMENT 'Gross value amount visible on the invoice. It is the gross total considering all the different order positions and their respective price conditions (in case of cust_order -> sum of all different conditions, in case of internal processes what it is been paid via invoice)',
   INVOICE_PRICE_VAT_LOCAL_VAL         NUMBER(38, 5)   COMMENT 'VAT value amount visible on the invoice. It is the VAT total considering all the different order positions and their respective price conditions (in case of cust_order -> sum of all different conditions, in case of internal processes what it is been paid via invoice)',
   ADD_DELIVERY_PAUSHAL_NET_LOCAL_VAL  NUMERIC(38,5)   COMMENT 'Additional net delivery fee/paushal for special destinations (Distribution Zones),  splitted per every order position in local currency.',
   CUST_ORDER_PERFORM_DT               DATE            COMMENT 'Date when goods leave the warehouse for delivery to the customer. It serves as the legal and fiscal date for fulfilling a customer''s order. This date is mandatory for OSES migrated sales orders, where it is always populated from SAP.',
   DWH_CREATED_TMSP                    TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
   DWH_UPDATED_TMSP                    TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was last updated.',
   DWH_SRC_FILE_NAME                   VARCHAR(255)    NOT NULL COMMENT 'The path and the name of the file(s) from which this record was loaded.',   
   CONSTRAINT PK_T_ETL_ORDER_POSITION PRIMARY KEY (CUST_ORDER_SID, CUST_ORDER_POS_NR) NOT ENFORCED 
)  COMMENT = 'The order placed from a customer within the onlineshop to receive the wanted items. Such orders can be also cancelled, returned or free resends to customers.';
